mapper.update:
UPDATE tasks
title = #{title}, content = #{content, jdbcType=CLOB}, project_member_id = #{projectMemberId}, status = #{status}, progress = #{progress}, start_at = TO_DATE(#{startAt}, 'YYYY-MM-DD'), "END" = TO_DATE(#{endAt}, 'YYYY-MM-DD'), updated = SYSDATE
WHERE task_id = #{taskId}

UPDATE sub_tasks
title = #{title}, content = #{content, jdbcType=CLOB}, project_member_id = #{projectMemberId}, status = #{status}, progress = #{progress}, start_at = TO_DATE(#{startAt}, 'YYYY-MM-DD'), "END" = TO_DATE(#{endAt}, 'YYYY-MM-DD'), updated = SYSDATE
WHERE sub_task_id = #{subTaskId}

UPDATE sub_tasks
SET deleted = SYSDATE, updated = SYSDATE
WHERE sub_task_id = #{subTaskId}
